-- Carbon platform · product specifications, part 3 of 7
--
-- 1572 products, each pointing at its texts.
-- Run every part in order. Safe to re-run.

on conflict (product_code) do update set name = excluded.name, main_name = excluded.main_name, main_slug = excluded.main_slug,
  variant = excluded.variant, tech = excluded.tech, quality = excluded.quality, pack = excluded.pack,
  use_note = excluded.use_note, storage = excluded.storage, confirm = excluded.confirm;
